/** PENDING_PAYMENT のときだけ移す。移せなければ false */
async settle(id: string, to: 'PAID' | 'PAYMENT_FAILED', chargeId?: string): Promise<boolean> {
  const result = this.#db
    .prepare(
      `UPDATE orders SET status = ?, charge_id = ?, updated_at = ?
       WHERE id = ? AND status = 'PENDING_PAYMENT'`,
    )
    .run(to, chargeId ?? null, this.#now().toISOString(), id);
  return result.changes === 1;
}
